{
  "concept": "Chemical equilibrium is a dynamic state reached when the forward and reverse reaction rates become exactly equal, which locks the macroscopic concentrations of reactants and products at constant levels.",
  "figureType": "diagram",
  "elements": [
    "Vial icon indicating bulk gas color (blends from colorless to deep brown)",
    "Circular magnified view containing gas particles",
    "N2O4 molecules (two blue nitrogen atoms, four red oxygen atoms)",
    "NO2 molecules (one blue nitrogen atom, two red oxygen atoms)",
    "Graph x-axis (Time) and y-axis (Concentration or Rate, depending on toggle)",
    "Blue curve: represents [N2O4] in Concentration view, or forward rate k_f[N2O4] in Rate view",
    "Red curve: represents [NO2] in Concentration view, or reverse rate k_r[NO2]^2 in Rate view",
    "Yellow shaded background region labeled 'Equilibrium achieved'",
    "Vertical dashed line marking the onset of equilibrium",
    "Movable vertical marker line representing current time",
    "Labels: 'N2O4', 'NO2', 'k_f[N2O4]', 'k_r[NO2]^2'"
  ],
  "interactions": [
    {
      "id": "time",
      "type": "slider",
      "label": "Time",
      "range": [0, 10, 0.1],
      "default": 0,
      "teaches": "Moving forward in time tracks the reaction's progress: the molecular mix updates, the vial color darkens, and the graphs trace the changing rates and concentrations until they stabilize."
    },
    {
      "id": "initialConcentration",
      "type": "slider",
      "label": "Initial [N2O4]",
      "range": [0.2, 1.0, 0.1],
      "default": 1.0,
      "teaches": "Changing the starting amount shifts the absolute final concentrations, but equilibrium is still fundamentally governed by the point where forward and reverse rates intersect."
    },
    {
      "id": "graphView",
      "type": "toggle",
      "label": "Graph Y-Axis",
      "options": ["Concentration", "Rate"],
      "default": "Concentration",
      "teaches": "While reactant and product concentrations plateau at different, unequal levels, the forward and reverse reaction rates always plateau at the exact same level."
    }
  ],
  "demo_steps": [
    {
      "title": "Initial State",
      "narration": "At t = 0, the container has only N2O4. The forward reaction rate is at its maximum, while the reverse rate is exactly zero because no NO2 exists yet.",
      "state": {
        "time": 0,
        "initialConcentration": 1.0,
        "graphView": "Rate"
      }
    },
    {
      "title": "Pre-equilibrium",
      "narration": "As time progresses, N2O4 breaks down into NO2. The forward rate drops while the reverse rate climbs. Switch to the concentration view to see NO2 accumulating.",
      "state": {
        "time": 3.5,
        "initialConcentration": 1.0,
        "graphView": "Concentration"
      }
    },
    {
      "title": "Equilibrium Achieved",
      "narration": "Eventually, the concentrations stop changing. This happens not because the reaction stops, but because the forward and reverse rates have become exactly equal.",
      "state": {
        "time": 8.0,
        "initialConcentration": 1.0,
        "graphView": "Rate"
      }
    }
  ],
  "keyInsight": "Equilibrium does not mean reactant and product concentrations are equal; it means the forward and reverse reaction rates are equal, which freezes the concentrations in place.",
  "reconstructionNotes": "Layout: Top half is a single dynamic molecular view (vial + magnified circle) that updates based on the time slider, rather than three static panels. Bottom half is a single graph area that switches between Concentration and Rate views based on the toggle. Ensure the vertical time marker sweeps across the graph and simultaneously updates the top visual's N2O4/NO2 particle ratio and vial color. Curve shapes: NO2 rises twice as fast as N2O4 falls (due to stoichiometry). In Rate view, the two curves must seamlessly merge into a single horizontal line at equilibrium."
}

