// @FIGURE_CODE_BEGIN
const draw = SVG().addTo('#container').size('100%', '100%');
const frame = setPlotFrame({ xDomain: [-1.5, 10.5], yDomain: [-0.4, 2.4], margin: 40, draw: draw });

let mode = 'Rate';
let A0 = 1.0;
let t_current = 0;

// Fixed randomized mapping to avoid wave-like breaking when iterating
const breakOrder = [4, 1, 7, 2, 8, 0, 5, 9, 3, 6];
const siteDefs = [
  { x: -35, y: -45, r: 15 },
  { x: 30,  y: -50, r: 75 },
  { x: -50, y: 5,   r: -30 },
  { x: 45,  y: -5,  r: 45 },
  { x: -20, y: -15, r: -80 },
  { x: 15,  y: 25,  r: 10 },
  { x: -30, y: 45,  r: 120 },
  { x: 35,  y: 40,  r: -45 },
  { x: -5,  y: -65, r: 0 },
  { x: -5,  y: 60,  r: 90 }
];

const graphGroup = draw.group();
const topGroup = draw.group();

// --- Background Grid & Regions ---
const eqRegion = graphGroup.rect().fill({ color: '#f5deb3', opacity: 0.4 });
const xAxis = graphGroup.line().stroke({ width: 2, color: '#333' });
const yAxis = graphGroup.line().stroke({ width: 2, color: '#333' });
const xAxisArrow = graphGroup.polygon('0,0 -10,-4 -10,4').fill('#333');
const yAxisArrow = graphGroup.polygon('0,0 -4,10 4,10').fill('#333');

const eqLine = graphGroup.line().stroke({ width: 2, color: '#333', dasharray: '5,5' });
const eqText = graphGroup.text('Equilibrium\nachieved').font({ size: 12, family: 'sans-serif' }).attr({'text-anchor': 'middle'});
const zeroLabel = graphGroup.text('0').font({ size: 12, family: 'sans-serif', fill: '#000' }).attr({'text-anchor': 'middle'});

const timeMarker = graphGroup.line().stroke({ width: 2, color: '#666', dasharray: '4,4' });

// --- Kinetics Formulas ---
const fBlue = (t) => mode === 'Concentration'
  ? A0 * (1 - 0.6 * (1 - Math.exp(-t/1.5)))       // [N2O4]
  : A0 * (1 - 0.6 * (1 - Math.exp(-t/1.5)));       // Rate_f (k_f[N2O4])

const fRed = (t) => mode === 'Concentration'
  ? 1.2 * A0 * (1 - Math.exp(-t/1.5))              // [NO2]
  : 0.4 * A0 * Math.pow(1 - Math.exp(-t/1.5), 2);  // Rate_r (k_r[NO2]^2)

const curveBlue = plotFunction('blueCurve', {
  fn: fBlue,
  domain: [0, 10],
  samples: 200,
  stroke: '#4a75b5',
  width: 3
});

const curveRed = plotFunction('redCurve', {
  fn: fRed,
  domain: [0, 10],
  samples: 200,
  stroke: '#c85a4f',
  width: 3
});

const labelBlue = graphGroup.text('')
  .font({ size: 12, family: 'sans-serif', fill: '#4a75b5', weight: 'bold' })
  .attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':3, 'stroke-linejoin':'round' });
const labelRed = graphGroup.text('')
  .font({ size: 12, family: 'sans-serif', fill: '#c85a4f', weight: 'bold' })
  .attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':3, 'stroke-linejoin':'round' });

const yAxisLabel = graphGroup.text('').font({ size: 13, family: 'sans-serif', fill: '#000' }).attr({ transform: 'rotate(-90)' });
const xAxisLabel = graphGroup.text('Time').font({ size: 13, family: 'sans-serif', fill: '#000' });

// --- Top Visual Elements (Vial & Particles) ---
const vialGroup = topGroup.group();
const tube = vialGroup.path('M -15,-50 L -15,50 A 15,15 0 0,0 15,50 L 15,-50 Z').fill('#fff').stroke({ color: '#888', width: 3 });
const liquidElement = vialGroup.path('M -13,-10 L -13,50 A 13,13 0 0,0 13,50 L 13,-10 Z').fill('#e6f0fa');
vialGroup.ellipse(30, 10).center(0, -50).fill('#fff').stroke({ color: '#888', width: 3 });

const arrowPath = topGroup.path().fill('#ccc').stroke({color: '#888', width: 2, linejoin: 'round'});
const magCircle = topGroup.circle().fill('#f8f9fa').stroke({ color: '#888', width: 4 });

const moleculesGroup = topGroup.group();
let molNodes = [];

function createN2O4(parent) {
  const g = parent.group();
  g.circle(12).fill('#3366cc').center(-6, 0); // N atoms
  g.circle(12).fill('#3366cc').center(6, 0);
  g.circle(10).fill('#cc2222').center(-12, 10); // O atoms
  g.circle(10).fill('#cc2222').center(-12, -10);
  g.circle(10).fill('#cc2222').center(12, 10);
  g.circle(10).fill('#cc2222').center(12, -10);
  return g;
}

function createNO2(parent) {
  const g = parent.group();
  g.circle(12).fill('#3366cc').center(0, 0); // N atom
  g.circle(10).fill('#cc2222').center(-9, 7); // O atoms
  g.circle(10).fill('#cc2222').center(9, 7);
  return g;
}

for (let i = 0; i < 10; i++) {
  const siteG = moleculesGroup.group();
  const n2o4 = createN2O4(siteG);
  const no2_1 = createNO2(siteG).center(-14, 0).hide();
  const no2_2 = createNO2(siteG).center(14, 0).hide();
  molNodes.push({ siteG, n2o4, no2_1, no2_2 });
}

function interpolateColor(color1, color2, factor) {
  factor = Math.max(0, Math.min(1, factor));
  const c1 = color1.slice(1).match(/.{2}/g).map(x => parseInt(x, 16));
  const c2 = color2.slice(1).match(/.{2}/g).map(x => parseInt(x, 16));
  const r = Math.round(c1[0] + (c2[0] - c1[0]) * factor);
  const g = Math.round(c1[1] + (c2[1] - c1[1]) * factor);
  const b = Math.round(c1[2] + (c2[2] - c1[2]) * factor);
  return `rgb(${r},${g},${b})`;
}

// --- Layout & Rendering ---
function updateGraph() {
  const originX = plotX(0);
  const originY = plotY(0);
  const maxX = plotX(10.5);
  const maxY = plotY(1.4);

  xAxis.plot(originX, originY, maxX, originY);
  yAxis.plot(originX, originY, originX, maxY);
  xAxisArrow.attr('transform', `translate(${maxX}, ${originY})`);
  yAxisArrow.attr('transform', `translate(${originX}, ${maxY})`);

  zeroLabel.center(originX, originY + 12);
  xAxisLabel.center(plotX(5), originY + 22);
  yAxisLabel.text(mode === 'Concentration' ? 'Concentration' : 'Rate');
  yAxisLabel.center(originX - 25, plotY(0.7));

  const eqX = plotX(5);
  eqLine.plot(eqX, originY, eqX, maxY);
  eqRegion.plot(eqX, maxY).size(Math.max(0, plotX(10) - eqX), originY - maxY);
  eqText.center((eqX + plotX(10)) / 2, plotY(0.9));

  curveBlue.setFn(fBlue);
  curveRed.setFn(fRed);

  if (mode === 'Concentration') {
    labelBlue.text('N₂O₄').center(plotX(7.5), plotY(fBlue(7.5)) - 14);
    labelRed.text('NO₂').center(plotX(7.5), plotY(fRed(7.5)) + 14);
  } else {
    labelBlue.text('k_f[N₂O₄]').center(plotX(2), plotY(fBlue(2)) + 16);
    labelRed.text('k_r[NO₂]²').center(plotX(2), plotY(fRed(2)) - 16);
  }
}

function updateTopAndMolecules() {
  const cx = plotX(7.5);
  const cy = plotY(2.0);
  const r = Math.min(frame.width * 0.16, 110);
  const scale = r / 100;

  magCircle.radius(r).center(cx, cy);

  const vx = plotX(2.5);
  const vy = plotY(2.1);
  vialGroup.attr('transform', `translate(${vx}, ${vy}) rotate(30) scale(${scale * 0.95})`);

  const ax = plotX(4.7);
  const ay = plotY(2.0);
  arrowPath.plot(`M -15,-8 L 8,-8 L 8,-16 L 25,0 L 8,16 L 8,8 L -15,8 Z`)
           .attr('transform', `translate(${ax}, ${ay}) scale(${scale * 0.9})`);

  moleculesGroup.attr('transform', `translate(${cx}, ${cy})`);

  const n2o4_conc = A0 * (1 - 0.6 * (1 - Math.exp(-t_current/1.5)));
  const numActiveSites = Math.round(A0 * 10);
  const numUnbroken = Math.round(n2o4_conc * 10);

  let activeIndices = [];
  for(let i=0; i<numActiveSites; i++) activeIndices.push(i);
  activeIndices.sort((a, b) => breakOrder[a] - breakOrder[b]);

  let unbrokenSet = new Set(activeIndices.slice(0, numUnbroken));

  for (let i = 0; i < 10; i++) {
    const node = molNodes[i];
    const def = siteDefs[i];

    if (i < numActiveSites) {
      node.siteG.show();
      node.siteG.attr('transform', `translate(${def.x * scale}, ${def.y * scale}) rotate(${def.r}) scale(${scale * 0.75})`);

      if (unbrokenSet.has(i)) {
        node.n2o4.show();
        node.no2_1.hide();
        node.no2_2.hide();
      } else {
        node.n2o4.hide();
        node.no2_1.show();
        node.no2_2.show();
      }
    } else {
      node.siteG.hide();
    }
  }

  const no2_conc = 1.2 * A0 * (1 - Math.exp(-t_current/1.5));
  liquidElement.fill(interpolateColor('#e6f0fa', '#d97b27', no2_conc / 1.2));
}

function updateTimeMarker() {
  const tx = plotX(t_current);
  timeMarker.plot(tx, plotY(0), tx, plotY(1.4));
}

function updateAll() {
  updateGraph();
  updateTopAndMolecules();
  updateTimeMarker();
}

window.update_time = function(v) {
  t_current = v;
  updateAll();
};

window.update_initialConcentration = function(v) {
  A0 = v;
  updateAll();
};

window.update_graphView = function(val) {
  mode = val;
  updateAll();
};

// --- Interactivity ---
vialGroup.css('cursor', 'pointer')
  .on('mousemove', e => showTooltip('The bulk color of the gas becomes darker brown as the concentration of NO₂ increases.', e))
  .on('mouseleave', () => hideTooltip());

eqRegion.css('cursor', 'pointer')
  .on('mousemove', e => showTooltip('Once equilibrium is reached, macroscopic concentrations remain constant because forward and reverse rates are equal.', e))
  .on('mouseleave', () => hideTooltip());

document.addEventListener('fig-resize', updateAll);

// --- Demo Step Player ---
let currentStep = 0;
const steps = [
  {
    title: "Initial State",
    narration: "At t = 0, the container has only N₂O₄. The forward reaction rate is at its maximum, while the reverse rate is exactly zero because no NO₂ exists yet.",
    state: { time: 0, initialConcentration: 1, graphView: "Rate" }
  },
  {
    title: "Pre-equilibrium",
    narration: "As time progresses, N₂O₄ breaks down into NO₂. The forward rate drops while the reverse rate climbs. Switch to the concentration view to see NO₂ accumulating.",
    state: { time: 3.5, initialConcentration: 1, graphView: "Concentration" }
  },
  {
    title: "Equilibrium Achieved",
    narration: "Eventually, the concentrations stop changing. This happens not because the reaction stops, but because the forward and reverse rates have become exactly equal.",
    state: { time: 8, initialConcentration: 1, graphView: "Rate" }
  }
];

window.nextStep = function() {
  if (currentStep < steps.length - 1) {
    currentStep++;
    applyStep(currentStep);
  }
};
window.prevStep = function() {
  if (currentStep > 0) {
    currentStep--;
    applyStep(currentStep);
  }
};

function applyStep(idx) {
  const step = steps[idx];
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = `Step ${idx + 1} of ${steps.length}`;

  if (step.state.time !== undefined) {
    document.getElementById('timeInput').value = step.state.time;
    document.getElementById('timeVal').value = step.state.time;
    t_current = step.state.time;
  }
  if (step.state.initialConcentration !== undefined) {
    document.getElementById('initialConcentrationInput').value = step.state.initialConcentration;
    document.getElementById('initialConcentrationVal').value = step.state.initialConcentration;
    A0 = step.state.initialConcentration;
  }
  if (step.state.graphView !== undefined) {
    document.getElementById('graphViewInput').value = step.state.graphView;
    mode = step.state.graphView;
  }
  updateAll();
}

// Ensure first frame layout finishes rendering properly
setTimeout(() => {
  applyStep(0);
  window.__markRendered();
}, 20);
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

