// --- Kinetics Formulas ---
// A smooth step function that hits exactly 1 at t = 5, with max slope at t = 0 and 0 slope at t = 5
function getP(t) {
  if (t >= 5) return 1;
  const x = t / 5;
  return 1 - (1 - x) * (1 - x);
}

const fBlue = (t) => {
  const p = getP(t);
  return mode === 'Concentration'
    ? A0 * (1 - 0.6 * p)        // [N2O4]
    : A0 * (1 - 0.6 * p);       // Rate_f (k_f[N2O4])
};

const fRed = (t) => {
  const p = getP(t);
  return mode === 'Concentration'
    ? 1.2 * A0 * p              // [NO2]
    : 0.4 * A0 * p * p;         // Rate_r (k_r[NO2]^2)
};

