            .attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':4, 'stroke-linejoin':'round' });
  }
}

function updateTopAndMolecules() {
  const cx = plotX(7.5);
  const cy = plotY(2.0);
  const r = Math.min(frame.width * 0.16, 110);
  const scale = r / 100;

  magCircle.radius(r).center(cx, cy);

  const vx = plotX(2.5);
  const vy = plotY(2.1);
  vialGroup.attr('transform', `translate(${vx}, ${vy}) rotate(30) scale(${scale * 0.95})`);

  const ax = plotX(4.7);
  const ay = plotY(2.0);
  arrowPath.plot(`M -15,-8 L 8,-8 L 8,-16 L 25,0 L 8,16 L 8,8 L -15,8 Z`)
           .attr('transform', `translate(${ax}, ${ay}) scale(${scale * 0.9})`);

  const phaseText = t_current === 0 ? 't = 0' : (t_current < 5 ? 'pre-equilibrium' : 'at equilibrium');
  phaseLabel.text(phaseText).center(plotX(5), plotY(2.45));

  moleculesGroup.attr('transform', `translate(${cx}, ${cy})`);

  const n2o4_conc = A0 * (1 - 0.6 * getP(t_current));
  const numActiveSites = Math.round(A0 * 10);
  const numUnbroken = Math.round(n2o4_conc * 10);

  let activeIndices = [];
  for(let i=0; i<numActiveSites; i++) activeIndices.push(i);
  activeIndices.sort((a, b) => breakOrder[a] - breakOrder[b]);

  let unbrokenSet = new Set(activeIndices.slice(0, numUnbroken));

  for (let i = 0; i < 10; i++) {
    const node = molNodes[i];
    const def = siteDefs[i];

    if (i < numActiveSites) {
      node.siteG.show();
      node.siteG.attr('transform', `translate(${def.x * scale}, ${def.y * scale}) rotate(${def.r}) scale(${scale * 0.75})`);

      if (unbrokenSet.has(i)) {
        node.n2o4.show();
        node.no2_1.hide();
        node.no2_2.hide();
      } else {
        node.n2o4.hide();
        node.no2_1.show();
        node.no2_2.show();
      }
    } else {
      node.siteG.hide();
    }
  }

  // Position specific molecular labels inside magnifier
  const siteN2O4 = siteDefs[5];
  const targetNx = cx + siteN2O4.x * scale;
  const targetNy = cy + siteN2O4.y * scale;

  const textNx = cx - r + 15;
  const textNy = cy + r + 25;
  textN2O4.center(textNx, textNy);
  lineN2O4.plot(textNx, textNy - 12, targetNx, targetNy);
  dotN2O4.center(targetNx, targetNy);

  const textOx = cx + r - 15;
  const textOy = cy + r + 25;

  if (numUnbroken < numActiveSites) {
