    lineNO2.show().plot(textOx, textOy - 12, targetOx, targetOy);
    dotNO2.show().center(targetOx, targetOy);
  } else {
    textNO2.hide();
    lineNO2.hide();
    dotNO2.hide();
  }

  // Update vial gas color
  const no2_conc = 1.2 * A0 * getP(t_current);
  liquidElement.fill(interpolateColor('#e6f0fa', '#d97b27', no2_conc / 1.2));
}

