  g.circle(14).fill('#c85a4f').center(13, 11).stroke({width: 1.5, color: '#333'});
  g.circle(14).fill('#c85a4f').center(13, -11).stroke({width: 1.5, color: '#333'});
  g.circle(16).fill('#4a75b5').center(-5, 0).stroke({width: 1.5, color: '#333'}); 
  g.circle(16).fill('#4a75b5').center(5, 0).stroke({width: 1.5, color: '#333'});
  return g;
}

function createNO2(parent) {
  const g = parent.group();
  g.circle(14).fill('#c85a4f').center(-10, 8).stroke({width: 1.5, color: '#333'});
  g.circle(14).fill('#c85a4f').center(10, 8).stroke({width: 1.5, color: '#333'});
  g.circle(16).fill('#4a75b5').center(0, 0).stroke({width: 1.5, color: '#333'});
  return g;
}

for (let i = 0; i < 10; i++) {
  const siteG = moleculesGroup.group();
  const n2o4 = createN2O4(siteG);
  const no2_1 = createNO2(siteG).center(-14, 0).hide();
  const no2_2 = createNO2(siteG).center(14, 0).hide();
  molNodes.push({ siteG, n2o4, no2_1, no2_2 });
}

const molLabelsGroup = topGroup.group();
const lineN2O4 = molLabelsGroup.line().stroke({ width: 1.5, color: '#333' });
const dotN2O4 = molLabelsGroup.circle(6).fill('#333');
const textN2O4 = molLabelsGroup.text('N₂O₄').font({ size: 14, family: 'sans-serif', weight: 'bold' });

const lineNO2 = molLabelsGroup.line().stroke({ width: 1.5, color: '#333' });
const dotNO2 = molLabelsGroup.circle(6).fill('#333');
const textNO2 = molLabelsGroup.text('NO₂').font({ size: 14, family: 'sans-serif', weight: 'bold' });

function interpolateColor(color1, color2, factor) {
  factor = Math.max(0, Math.min(1, factor));
  const c1 = color1.slice(1).match(/.{2}/g).map(x => parseInt(x, 16));
  const c2 = color2.slice(1).match(/.{2}/g).map(x => parseInt(x, 16));
  const r = Math.round(c1[0] + (c2[0] - c1[0]) * factor);
  const g = Math.round(c1[1] + (c2[1] - c1[1]) * factor);
  const b = Math.round(c1[2] + (c2[2] - c1[2]) * factor);
  return `rgb(${r},${g},${b})`;
}

// --- Layout & Rendering ---
function updateGraph() {
  const originX = plotX(0);
  const originY = plotY(0);
  const maxX = plotX(10.5);
  const maxY = plotY(1.6); // Axis ends at 1.6 to leave top room for molecules

  xAxis.plot(originX, originY, maxX, originY);
  yAxis.plot(originX, originY, originX, maxY);
  xAxisArrow.attr('transform', `translate(${maxX}, ${originY})`);
  yAxisArrow.attr('transform', `translate(${originX}, ${maxY})`);

  zeroLabel.center(originX, originY + 12);
  xAxisLabel.center(plotX(5), originY + 24);

  yAxisLabel.clear();
  yAxisLabel.text(mode === 'Concentration' ? 'Concentration' : 'Rate')
            .center(originX - 35, (originY + maxY) / 2)
            .attr({ transform: `rotate(-90, ${originX - 35}, ${(originY + maxY) / 2})` });

  const eqX = plotX(5);
  eqLine.plot(eqX, originY, eqX, maxY);

  eqRegion.attr({
    x: eqX,
    y: maxY,
    width: Math.max(0, maxX - eqX),
    height: Math.max(0, originY - maxY)
  });

  // Safe vertical positioning avoiding the magnifier above and curves below
  eqText.center(plotX(7.75), plotY(0.75));

  curveBlue.setFn(fBlue);
  curveRed.setFn(fRed);

  if (mode === 'Concentration') {
    labelBlue.clear().text('N₂O₄')
             .center(plotX(7.5), plotY(fBlue(7.5)) - 18)
             .attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':4, 'stroke-linejoin':'round' });
    labelRed.clear().text('NO₂')
            .center(plotX(7.5), plotY(fRed(7.5)) + 18)
            .attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':4, 'stroke-linejoin':'round' });
  } else {
    labelBlue.clear().text(function(add) {
      add.tspan('k');
      add.tspan('f').font({size: 10}).dy(5);
      add.tspan(' [N₂O₄]').dy(-5);
    })
    .center(plotX(2.5), plotY(fBlue(2.5)) - 24)
    .attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':4, 'stroke-linejoin':'round' });

    labelRed.clear().text(function(add) {
      add.tspan('k');
      add.tspan('r').font({size: 10}).dy(5);
      add.tspan(' [NO₂]²').dy(-5);
    })
    .center(plotX(2.5), plotY(fRed(2.5)) + 24)
    .attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':4, 'stroke-linejoin':'round' });
  }
}

function updateTopAndMolecules() {
  const cx = plotX(7.5);
  const cy = plotY(1.8);
  const r = Math.min(frame.width * 0.16, 100);
  const scale = r / 100;

  magCircle.radius(r).center(cx, cy);

  const vx = plotX(2.5);
  const vy = plotY(1.9);
  vialGroup.attr('transform', `translate(${vx}, ${vy}) rotate(30) scale(${scale * 0.95})`);

  const ax = plotX(4.7);
  const ay = plotY(1.85);
  arrowPath.plot(`M -15,-8 L 8,-8 L 8,-16 L 25,0 L 8,16 L 8,8 L -15,8 Z`)
           .attr('transform', `translate(${ax}, ${ay}) scale(${scale * 0.9})`);

  const phaseText = t_current === 0 ? 't = 0' : (t_current < 5 ? 'pre-equilibrium' : 'at equilibrium');
  phaseLabel.text(phaseText).center(plotX(5), plotY(2.45));

  moleculesGroup.attr('transform', `translate(${cx}, ${cy})`);

  const n2o4_conc = A0 * (1 - 0.6 * getP(t_current));
  const numActiveSites = Math.round(A0 * 10);
  const numUnbroken = Math.round(n2o4_conc * 10);

  let activeIndices = [];
  for(let i = 0; i < numActiveSites; i++) activeIndices.push(i);
  activeIndices.sort((a, b) => breakOrder[a] - breakOrder[b]);

  let unbrokenSet = new Set(activeIndices.slice(0, numUnbroken));

  let bestN2O4 = -1, minXN2O4 = 999;
  let bestNO2 = -1, maxXNO2 = -999;

  for (let i = 0; i < 10; i++) {
    const node = molNodes[i];
    const def = siteDefs[i];

    if (i < numActiveSites) {
      node.siteG.show();
      node.siteG.attr('transform', `translate(${def.x * scale}, ${def.y * scale}) rotate(${def.r}) scale(${scale * 0.75})`);

      if (unbrokenSet.has(i)) {
        node.n2o4.show(); node.no2_1.hide(); node.no2_2.hide();
        if (def.x < minXN2O4) { minXN2O4 = def.x; bestN2O4 = i; }
      } else {
        node.n2o4.hide(); node.no2_1.show(); node.no2_2.show();
        if (def.x > maxXNO2) { maxXNO2 = def.x; bestNO2 = i; }
      }
    } else {
      node.siteG.hide();
    }
  }

  // Draw labels dynamically targeting left-most N2O4 and right-most NO2 to prevent collision
  if (bestN2O4 !== -1) {
    const site = siteDefs[bestN2O4];
    const targetNx = cx + site.x * scale;
    const targetNy = cy + site.y * scale;
    const textNx = cx - r - 20; 
    const textNy = cy + 20;     

    textN2O4.show().center(textNx, textNy);
    lineN2O4.show().plot(textNx + 15, textNy, targetNx, targetNy);
    dotN2O4.show().center(targetNx, targetNy);
  } else {
    textN2O4.hide(); lineN2O4.hide(); dotN2O4.hide();
  }

  if (bestNO2 !== -1) {
    const site = siteDefs[bestNO2];
    const targetOx = cx + site.x * scale;
    const targetOy = cy + site.y * scale;
    const textOx = cx + r + 20; 
    const textOy = cy - 20;     

    textNO2.show().center(textOx, textOy);
    lineNO2.show().plot(textOx - 15, textOy, targetOx, targetOy);
    dotNO2.show().center(targetOx, targetOy);
  } else {
    textNO2.hide(); lineNO2.hide(); dotNO2.hide();
  }

  // Blend vial contents from colorless to deep brown based on NO2 amount
  const no2_conc = 1.2 * A0 * getP(t_current);
  const gasColor = interpolateColor('#ffffff', '#d97b27', no2_conc / 1.2);
  liquidElement.fill(gasColor);
  topEllipse.fill(gasColor);
}

function updateTimeMarker() {
  const tx = plotX(t_current);
  timeMarker.plot(tx, plotY(0), tx, plotY(1.6));
  timeMarkerDot.center(tx, plotY(0));
}

function updateAll() {
  updateGraph();
  updateTopAndMolecules();
  updateTimeMarker();
}

window.update_time = function(v) {
  t_current = v;
  updateAll();
};

window.update_initialConcentration = function(v) {
  A0 = v;
  updateAll();
};

window.update_graphView = function(val) {
  mode = val;
  updateAll();
};

// --- Interactivity ---
vialGroup.css('cursor', 'pointer')
  .on('mousemove', e => showTooltip('The bulk color of the gas becomes darker brown as the concentration of NO₂ increases.', e))
  .on('mouseleave', () => hideTooltip());

eqRegion.css('cursor', 'pointer')
  .on('mousemove', e => showTooltip('Once equilibrium is reached, macroscopic concentrations remain constant because forward and reverse rates are equal.', e))
  .on('mouseleave', () => hideTooltip());

curveBlue.node.css('cursor', 'pointer')
  .on('mousemove', e => showTooltip(mode === 'Concentration' ? 'Concentration of reactant N₂O₄ drops as it is consumed.' : 'Forward reaction rate drops as reactant is depleted.', e))
  .on('mouseleave', () => hideTooltip());

curveRed.node.css('cursor', 'pointer')
  .on('mousemove', e => showTooltip(mode === 'Concentration' ? 'Concentration of product NO₂ rises as it is formed.' : 'Reverse reaction rate increases as product accumulates.', e))
  .on('mouseleave', () => hideTooltip());

document.addEventListener('fig-resize', updateAll);

// --- Demo Step Player ---
let currentStep = 0;
const steps = [
  {
    title: "Initial State",
    narration: "At t = 0, the container has only N₂O₄. The forward reaction rate is at its maximum, while the reverse rate is exactly zero because no NO₂ exists yet.",
    state: { time: 0, initialConcentration: 1, graphView: "Rate" }
  },
  {
    title: "Pre-equilibrium",
    narration: "As time progresses, N₂O₄ breaks down into NO₂. The forward rate drops while the reverse rate climbs. Switch to the concentration view to see NO₂ accumulating.",
    state: { time: 3.5, initialConcentration: 1, graphView: "Concentration" }
  },
  {
    title: "Equilibrium Achieved",
    narration: "Eventually, the concentrations stop changing. This happens not because the reaction stops, but because the forward and reverse rates have become exactly equal.",
    state: { time: 8, initialConcentration: 1, graphView: "Rate" }
  }
];

window.nextStep = function() {
  if (currentStep < steps.length - 1) {
    currentStep++;
    applyStep(currentStep);
  }
};
window.prevStep = function() {
  if (currentStep > 0) {
    currentStep--;
    applyStep(currentStep);
  }
};

function applyStep(idx) {
  const step = steps[idx];
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = `Step ${idx + 1} of ${steps.length}`;

  if (step.state.time !== undefined) {
    document.getElementById('timeInput').value = step.state.time;
    document.getElementById('timeVal').value = step.state.time;
    t_current = step.state.time;
  }
  if (step.state.initialConcentration !== undefined) {
    document.getElementById('initialConcentrationInput').value = step.state.initialConcentration;
    document.getElementById('initialConcentrationVal').value = step.state.initialConcentration;
    A0 = step.state.initialConcentration;
  }
  if (step.state.graphView !== undefined) {
    document.getElementById('graphViewInput').value = step.state.graphView;
    mode = step.state.graphView;
  }
  updateAll();
}

// Ensure first frame layout finishes rendering properly
setTimeout(() => {
  applyStep(0);
  window.__markRendered();
}, 20);
